const welcome=document.querySelector('#welcome'),story=document.querySelector('#story');
document.querySelector('#open-envelope').addEventListener('click',()=>{welcome.classList.add('opening');setTimeout(()=>{welcome.hidden=true;story.hidden=false;window.scrollTo(0,0);document.querySelector('#bouquet').focus({preventScroll:true});},650)});
document.querySelector('#bouquet').addEventListener('click',()=>document.querySelector('#letter-dialog').showModal());
const memories={mmu:{src:'assets/mmu.jpeg',alt:'Arisha at MMU Cyberjaya, where we first met',location:'MMU CYBERJAYA',title:'where it begins',description:''},melaka:{src:'assets/melaka.jpeg',alt:'Sof and Arisha together in Ayer Keroh, Melaka',location:'AYER KEROH, MELAKA',title:'you & me',description:''}};
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{const m=memories[button.dataset.photo];const img=document.querySelector('#memory-image');img.src=m.src;img.alt=m.alt;document.querySelector('#memory-location').textContent=m.location;document.querySelector('#memory-title').textContent=m.title;document.querySelector('#memory-description').textContent=m.description;document.querySelector('#photo-dialog').showModal()}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})});
document.querySelector('#restart').addEventListener('click',()=>{story.hidden=true;welcome.hidden=false;welcome.classList.remove('opening');window.scrollTo(0,0);document.querySelector('#open-envelope').focus()});
